# Installs the context-bar Claude Code mod on this PC.
# Usage (PowerShell):  powershell -ExecutionPolicy Bypass -File .\install-context-bar.ps1
$ErrorActionPreference = 'Stop'
$dest = Join-Path $env:USERPROFILE '.claude\mods\context-bar'
$files = @{
  '.claude-plugin/plugin.json' = ''
  'hooks/hooks.json' = 'eyAibW9kdWxlcyI6IFsiLi9yZWdpc3Rlci50c3giXSB9Cg=='
  'hooks/register.tsx' = ''
  'types/index.d.ts' = ''
  'tests/context-bar.test.tsx' = ''
}
foreach ($rel in $files.Keys) {
  $path = Join-Path $dest ($rel -replace '/', '\')
  New-Item -ItemType Directory -Force -Path (Split-Path $path) | Out-Null
  [IO.File]::WriteAllBytes($path, [Convert]::FromBase64String($files[$rel]))
}
Write-Host "Mod written to $dest"

# Register the folder in ~/.claude/settings.json (env.CLAUDE_CODE_PLUGIN_DIRS), keeping a backup.
$settings = Join-Path $env:USERPROFILE '.claude\settings.json'
if (Test-Path $settings) {
  Copy-Item $settings "$settings.bak" -Force
  $json = Get-Content $settings -Raw | ConvertFrom-Json
} else {
  $json = [pscustomobject]@{}
}
if (-not $json.PSObject.Properties['env']) { $json | Add-Member env ([pscustomobject]@{}) }
$current = $json.env.PSObject.Properties['CLAUDE_CODE_PLUGIN_DIRS']
$dirs = if ($current) { @($current.Value -split ';' | Where-Object { $_ }) } else { @() }
if ($dirs -notcontains $dest) { $dirs += $dest }
$json.env | Add-Member CLAUDE_CODE_PLUGIN_DIRS ($dirs -join ';') -Force
$json | ConvertTo-Json -Depth 32 | Set-Content $settings -Encoding UTF8
Write-Host "Registered in $settings (backup: settings.json.bak)"
Write-Host "Restart the Claude desktop app (or run: claude --plugin-dir `"$dest`"), then type /context-bar debug"
